mapper.select:
select mn.*, pp.P_Name as projectName,pp.P_Competent_Department as projectCompetentDepartmentId,sd.D_Name as projectCompetentDepartmentName,
       pp.P_Inv_Total as projectInvTotal,pp.P_Approve_Budget_Code as projectApproveBudgetCode,
       pp.P_Approve_Budget as projectApproveBudget,ibd.bd_approval_num as bdApprovalNum,
sc.C_Name as gfpApplicationCidName,
pp.P_Department as projectDepartmentId,
sd2.D_Name as projectDepartmentName
from Group_Fund_Plan mn
left join Pre_Project pp on mn.Project_ID = pp.P_ID
left join SYS_Department sd on pp.P_Competent_Department = sd.D_ID
left join Inv_Budget_Declare ibd on pp.P_ID = ibd.P_ID
left join SYS_Company sc on mn.gfp_Application_Cid = sc.C_ID
left join SYS_Department sd2 on pp.P_Department = sd2.D_ID
${params.authSql}
and mn.del_flag = 0

    
        
            and likePname(#{params.projectName},pp.P_Id)=true
        
        
            and pp.P_Name like concat('%',#{params.projectName},'%')
        
    


    and mn.Project_ID = #{params.projectId}


    and mn.group_Type = #{params.groupType}


    and mn.usa_Id = #{params.usaId}


    and mn.gfp_Application_Cid = #{params.gfpApplicationCid}


    and sc.C_Name like concat('%',#{params.gfpApplicationCidName},'%')


    and mn.Gfp_Fund_Demand_Amount >= #{params.gfpFundDemandAmountStart}


    and mn.Gfp_Fund_Demand_Amount <= #{params.gfpFundDemandAmountEnd}


    and mn.Create_Time >= #{params.createTimeStart}


    and mn.Create_Time <= #{params.createTimeEnd}


    and mn.Group_Id = #{params.groupId}


    and mn.Group_Main_Type = #{params.groupMainType}


    
        and mn.state = #{params.state}
    
    
        and mn.state != 3
    


    and mn.Create_Uname like concat('%',#{params.createUname},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc

select gfp.*, pp.P_Name as projectName,pp.P_Competent_Department as projectCompetentDepartmentId,sd.D_Name as projectCompetentDepartmentName, pp.P_Inv_Total as projectInvTotal,pp.P_Approve_Budget_Code as projectApproveBudgetCode, pp.P_Approve_Budget as projectApproveBudget,ibd.bd_approval_num as bdApprovalNum from Group_Fund_Plan gfp left join Pre_Project pp on gfp.Project_ID = pp.P_ID left join SYS_Department sd on pp.P_Competent_Department = sd.D_ID left join Inv_Budget_Declare ibd on pp.P_ID = ibd.P_ID
gfp.state !=3 and gfp.del_flag = 0
and gfp.Project_ID = #{params.projectId}
and gfp.Gfp_Year = #{params.gfpYear}
and gfp.Gfp_Month = #{params.gfpMonth}

select mn.*, con.Con_Name as gfpdContractName, CONCAT(gfp.Gfp_Year, '-', LPAD(gfp.Gfp_Month, 2, '0'), '-01') as gfpDate, sc.C_Name as payCompanyName, CASE WHEN gfpds.Ibb_Id IS NOT NULL THEN ibbd.Isbd_Fee_Type_Name ELSE iebd.Isbd_Fee_Type_Name END as budgetSubjectsName, CASE WHEN gfpds.Ibb_Id IS NOT NULL THEN ibbd.Isb_ID ELSE iebd.Isb_ID END as budgetSubjectsId from Group_Fund_Plan_Detail mn left join Group_Fund_Plan gfp on mn.Gfp_Id = gfp.id left join Con_Contract con on mn.Gfpd_Contract_Id = con.Con_Id left join sys_company sc on mn.pay_Company = sc.C_ID left join Group_Fund_Plan_Detail_Subject gfpds on mn.id = gfpds.gfpd_Id left join Investment_Budget_Breakdown_Details ibbd on gfpds.Ibb_Id = ibbd.id left join Investment_Estimate_Breakdown_Details iebd on gfpds.ieb_Id = iebd.id where gfp.State = 7 and gfp.del_flag = 0 and gfp.Group_Main_Type = '1'
and gfp.Project_ID = #{params.projectId}
and mn.Gfpd_Contract_Id = #{params.contractId}
and con.Con_Name like concat('%',#{params.pId},'%')
and mn.Gfpd_Contract_Id = #{params.contractId}
and mn.Gfpd_Type = #{params.gfpdType}
and mn.pay_Company = #{params.payCompany}
and gfp.group_Type = #{params.groupType}
and mn.cmp_Id = #{params.cmpId}
order by gfp.Create_Time desc
